<?php

namespace models\scolarite;

use core\Model;
use Database;
use models\acteurs\Etudiant;

/**
 * Modèle représentant la note/résultat obtenu par un étudiant à une évaluation (table TD_RESULTAT).
 *
 * @author  AutoGenerated / POO Refactor
 * @version 1.0
 */
class Resultat extends Model
{
    public string $PER_ID;
    public string $EVA_ID;
    public string $RES_NOTE;

    /**
     * Instancie et hydrate le modèle à partir d'un tableau associatif.
     *
     * @param array<string, mixed> $data
     * @return static
     */
    public static function fromArray(array $data): static
    {
        return (new static())->hydrate($data);
    }

    /**
     * Recherche un enregistrement par sa clé composite (PER_ID, EVA_ID).
     *
     * @param string $per_id
     * @param string $eva_id
     * @return static|null
     */
    public static function find(string $per_id, string $eva_id): ?static
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_RESULTAT WHERE PER_ID = ? AND EVA_ID = ? LIMIT 1');
        $stmt->execute([$per_id, $eva_id]);
        $row = $stmt->fetch();

        return $row ? (new static())->hydrate($row) : null;
    }

    /**
     * Récupère tous les enregistrements de la table.
     *
     * @return static[]
     */
    public static function findAll(): array
    {
        $stmt = Database::getInstance()->query('SELECT * FROM TD_RESULTAT');
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Récupère les instances Resultat associées à un objet Etudiant.
     *
     * @param Etudiant $source
     * @return static[]
     */
    public static function getFromEtudiant(Etudiant $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_RESULTAT WHERE PER_ID = ?');
        $stmt->execute([$source->PER_ID]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Navigue vers l'objet Etudiant parent lié à cet enregistrement.
     *
     * @return Etudiant|null
     */
    public function getEtudiant(): ?Etudiant
    {
        if (!isset($this->PER_ID)) {
            return null;
        }
        return Etudiant::findById($this->PER_ID);
    }

    /**
     * Récupère les instances Resultat associées à un objet Evaluation.
     *
     * @param Evaluation $source
     * @return static[]
     */
    public static function getFromEvaluation(Evaluation $source): array
    {
        $stmt = Database::getInstance()->prepare('SELECT * FROM TD_RESULTAT WHERE EVA_ID = ?');
        $stmt->execute([$source->EVA_ID]);
        $rows = $stmt->fetchAll();

        return array_map(fn($row) => (new static())->hydrate($row), $rows);
    }

    /**
     * Navigue vers l'objet Evaluation parent lié à cet enregistrement.
     *
     * @return Evaluation|null
     */
    public function getEvaluation(): ?Evaluation
    {
        if (!isset($this->EVA_ID)) {
            return null;
        }
        return Evaluation::findById($this->EVA_ID);
    }

}

if (!class_exists('models\Resultat', false)) {
    class_alias(Resultat::class, 'models\Resultat');
}
